return [{ json: { texto } }];

// Nodo Code: "Armar Prompt Rama A"
const temasExistentes = $('Buscar Contenidos a Generar').all();
const conocimiento = $('Consolidar Conocimiento1').first().json.texto;
const listaTemas = temasExistentes
  .map(item => `- ${item.json.fields["Idea Semilla"]} (${item.json.fields["Estado"]})`)
  .join("\n");
const prompt = `Sos un asistente de marketing de contenidos para una arquitecta que busca trabajo.
${conocimiento}
TEMAS YA EXISTENTES EN EL CALENDARIO (no los repitas):
${listaTemas}
Generá 4 nuevos "Ideas Semilla" para el próximo mes, uno por semana (Semana 1 a 4), 
que NO se repitan con los temas existentes ni con ningún subtema ya cubierto en ellos. 
Deben conectar con la información validada de la arquitecta.

El campo "tono" DEBE ser exactamente uno de estos 4 valores, sin agregar nada más: 
Inspiracional, Técnico, Cercano, Educativo.

Respondé ÚNICAMENTE en este formato JSON, sin texto adicional ni bloques de código markdown:
[
  { "semana": 1, "idea_semilla": "...", "tono": "..." },
  { "semana": 2, "idea_semilla": "...", "tono": "..." },
  { "semana": 3, "idea_semilla": "...", "tono": "..." },
  { "semana": 4, "idea_semilla": "...", "tono": "..." }
]`;
return [{ json: { prompt } }];

// Nodo Code: "Formatear Sugerencias WhatsApp"

const raw = $json.text.replace(/```json|```/g, "").trim();
const temas = JSON.parse(raw);

let mensaje = "✨ Temas sugeridos para el próximo mes:\n\n";

temas.forEach(t => {
  mensaje += `*Semana ${t.semana}*\n${t.idea_semilla}\nTono: ${t.tono}\n\n`;
});

mensaje += "Si te gusta alguno, cargalo manualmente en el Calendario de Contenido 📋";

return [{ json: { mensaje } }];

const conocimiento = $('Consolidar Conocimiento').first().json.texto;
const idea = $json.fields["Idea Semilla"];
const tono = $json.fields["Tono"];
const recordId = $json.id;

const prompt = `Sos un asistente de marketing de contenidos para una arquitecta que busca trabajo.

${conocimiento}

Idea Semilla: ${idea}
Tono: ${tono}

Generá dos piezas separadas y claramente etiquetadas:
1. Post de Instagram (tono visual, conciso, con hashtags relevantes)
2. Post de LinkedIn (tono profesional, orientado a networking)

Respondé ÚNICAMENTE en este formato exacto, sin bloques de código markdown:
INSTAGRAM:
[contenido]

LINKEDIN:
[contenido]`;

return [{ json: { prompt, recordId } }];

const raw = $json.text.replace(/```/g, "").trim();
const igMatch = raw.match(/INSTAGRAM:\s*([\s\S]*?)\s*LINKEDIN:/i);
const liMatch = raw.match(/LINKEDIN:\s*([\s\S]*)/i);

const instagram = igMatch ? igMatch[1].trim() : "⚠️ No se pudo generar (revisar manualmente)";
const linkedin = liMatch ? liMatch[1].trim() : "⚠️ No se pudo generar (revisar manualmente)";
const recordId = $('Armar Prompt Contenido').item.json.recordId;

return [{ json: { instagram, linkedin, recordId } }];

